CREATE DATABASE IF NOT EXISTS db_taller_mecanico CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_taller_mecanico;
CREATE TABLE IF NOT EXISTS clientes(id INT AUTO_INCREMENT PRIMARY KEY, identificador VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(120) NOT NULL,telefono VARCHAR(30),correo VARCHAR(120));
CREATE TABLE IF NOT EXISTS vehiculos(id INT AUTO_INCREMENT PRIMARY KEY,cliente_id INT NOT NULL,placa VARCHAR(20) NOT NULL UNIQUE,marca VARCHAR(60) NOT NULL,modelo VARCHAR(60) NOT NULL,anio INT,FOREIGN KEY(cliente_id) REFERENCES clientes(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS mecanicos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,telefono VARCHAR(30),especialidad VARCHAR(90));
CREATE TABLE IF NOT EXISTS repuestos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion VARCHAR(250),precio DECIMAL(12,2) NOT NULL,existencia INT NOT NULL DEFAULT 0,CHECK(precio>=0),CHECK(existencia>=0));
CREATE TABLE IF NOT EXISTS servicios(id INT AUTO_INCREMENT PRIMARY KEY,descripcion VARCHAR(150) NOT NULL,costo DECIMAL(12,2) NOT NULL,CHECK(costo>=0));
CREATE TABLE IF NOT EXISTS ordenes_trabajo(id INT AUTO_INCREMENT PRIMARY KEY,vehiculo_id INT NOT NULL,mecanico_id INT NOT NULL,problema TEXT NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_finalizacion DATETIME NULL,total DECIMAL(12,2) NOT NULL DEFAULT 0,FOREIGN KEY(vehiculo_id) REFERENCES vehiculos(id) ON DELETE RESTRICT,FOREIGN KEY(mecanico_id) REFERENCES mecanicos(id) ON DELETE RESTRICT,CHECK(estado IN ('PENDIENTE','EN PROCESO','FINALIZADA','CANCELADA')));
CREATE TABLE IF NOT EXISTS orden_servicios(id INT AUTO_INCREMENT PRIMARY KEY,orden_id INT NOT NULL,servicio_id INT NOT NULL,costo DECIMAL(12,2) NOT NULL,FOREIGN KEY(orden_id) REFERENCES ordenes_trabajo(id) ON DELETE RESTRICT,FOREIGN KEY(servicio_id) REFERENCES servicios(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS orden_repuestos(id INT AUTO_INCREMENT PRIMARY KEY,orden_id INT NOT NULL,repuesto_id INT NOT NULL,cantidad INT NOT NULL,precio DECIMAL(12,2) NOT NULL,CHECK(cantidad>0),FOREIGN KEY(orden_id) REFERENCES ordenes_trabajo(id) ON DELETE RESTRICT,FOREIGN KEY(repuesto_id) REFERENCES repuestos(id) ON DELETE RESTRICT);
